#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, k;
    cin >> n >> k;
    // Earliest index of each prefix-sum remainder; equal remainders bound a divisible interval.
    unordered_map<long long, int> first;
    first.reserve(2 * n + 2);
    first[0] = -1;
    long long prefix = 0;
    int answer = 0;
    for (int i = 0; i < n; i++) {
        long long amount;
        cin >> amount;
        prefix = ((prefix + amount) % k + k) % k;
        auto it = first.find(prefix);
        if (it != first.end()) answer = max(answer, i - it->second);
        else first[prefix] = i;
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        HashMap<Long, Integer> first = new HashMap<>();
        first.put(0L, -1);
        long prefix = 0;
        int answer = 0;
        for (int i = 0; i < n; i++) {
            prefix = Math.floorMod(prefix + nextLong(), k);
            Integer at = first.get(prefix);
            if (at != null) answer = Math.max(answer, i - at);
            else first.put(prefix, i);
        }
        System.out.print(answer + "\n");
    }
}
